import sys

def longestSubstring(N, S):
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    max_len = 0
    end_index = 0

    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            if S[i - 1] == S[j - 1]:
                if j - i > dp[i - 1][j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    if dp[i][j] > max_len:
                        max_len = dp[i][j]
                        end_index = i
                else:
                    dp[i][j] = 0
            else:
                dp[i][j] = 0

    if max_len == 0:
        return -1

    return S[end_index - max_len:end_index]

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        S = next(iterator)

        result = longestSubstring(N, S)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
